/*
 * A062996  Numbers whose sum of digits is greater than or equal to its
 *          product of digits.
 * https://oeis.org/A062996
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, nonn
 * Formula:   not stated
 * Range:     u8 n <= 95, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   digit_product, digit_sum
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A062996: Numbers whose sum of digits is greater than or equal to its product of digits. */
/* The sequence is generated by scanning positive integers and collecting those that satisfy sumDigits(num) >= prodDigits(num). */
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>
#include "../utils/digit_sum.h"
#include "../utils/digit_product.h"

/* Cache the sequence terms as they are discovered. */
static seq_t *term_cache = NULL;     /* array of terms */
static idx_t cache_len = 0;          /* number of terms cached */
static idx_t cache_cap = 0;          /* capacity of the array */
static uint64_t next_candidate = 1;  /* next integer to test */

/* Append a value to the cache, enlarging it if necessary. */
static void cache_append(seq_t val)
{
    if (cache_cap == 0) {
        cache_cap = 16;
        term_cache = (seq_t*)malloc(sizeof(seq_t) * cache_cap);
    } else if (cache_len == cache_cap) {
        cache_cap <<= 1;
        term_cache = (seq_t*)realloc(term_cache, sizeof(seq_t) * cache_cap);
    }
    term_cache[cache_len++] = val;
}

/* Main function required by the build. */
seq_t a(idx_t n)
{
    /* Ensure we have at least n terms cached. */
    while (cache_len < n) {
        seq_t cand = (seq_t)next_candidate;
        if (digit_sum(cand) >= digit_product(cand)) {
            cache_append(cand);
        }
        ++next_candidate;
    }
    return term_cache[n - 1];
}
